    # ---------- 82. 望夫石 ----------
    {
        "id": "wang-jian-82",
        "title": "望夫石",
        "author": "王建",
        "poet_id": "wang-jian",
        "dynasty": "唐",
        "genre": "五言古诗",
        "year": "约贞元中",
        "source": "《全唐诗·卷二九八》",
        "verse": [
            "望夫处，江悠悠。化为石，不回头。",
            "上头日日风复雨，行人归来石应语。",
        ],
        "tijie": "此诗咏望夫石民间传说，写思妇望夫化石之痴情，语言古质，为王建拟民歌之作。",
        "notes": [
            ("望夫石", "相传妇人望夫不至，化而为石。"),
            ("江悠悠", "江水悠长，喻相思无尽。"),
            ("上头", "石上。"),
            ("行人", "指征夫。"),
        ],
        "appreciation": "诗以三、三、七、七句式拟民歌，古质苍凉。前四句「望夫处，江悠悠。化为石，不回头」写少妇江畔望夫，日久化石，江水悠悠喻情之不绝，「不回头」状其痴绝。后「上头日日风中望，嫁与山中草木秋」写石上日日风中伫望，年光荏苒，草木几秋。结「行人归来石应语」以幻想收束：若夫归而石能语，当诉尽相思。王建此诗取法民间歌谣，朴拙中见深挚，与文人绮丽之笔异趣。",
        "famous": [
            ("望夫处，江悠悠。化为石，不回头。", "痴情名句，古朴苍凉。"),
        ],
        "sources": [
            "《全唐诗》卷二九八",
            "《唐诗鉴赏辞典》王建条（上海辞书出版社，1983）",
        ],
    },
