    # ---------- 126. 寻橦歌 ----------
    {
        "id": "wang-jian-126",
        "title": "寻橦歌",
        "author": "王建",
        "poet_id": "wang-jian",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷44》",
        "verse": [
            "人间百戏皆可学，寻橦不比诸馀乐。重梳短髻下金钿，",
            "红帽青巾各一边。身轻足捷胜男子，绕竿四面争先缘。",
            "习多倚附欹竿滑，上下蹁跹皆著袜。翻身垂颈欲落地，",
            "却住把腰初似歇。大竿百夫擎不起，袅袅半在青云里。",
            "纤腰女儿不动容，戴行直舞一曲终。回头但觉人眼见，",
            "矜难恐畏天无风。险中更险何曾失，山鼠悬头猿挂膝。",
            "小垂一手当舞盘，斜惨双蛾看落日。斯须改变曲解新，",
            "贵欲欢他平地人。散时满面生颜色，行步依前无气力。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 127. 铜雀台 ----------
    {
        "id": "wang-jian-127",
        "title": "铜雀台",
        "author": "王建",
        "poet_id": "wang-jian",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷45》",
        "verse": [
            "娇爱更何日，高台空数层。含啼映双袖，不忍看西陵。",
            "漳水东流无复来，百花辇路为苍苔。青楼月夜长寂寞，",
            "碧云日暮空裴回。君不见邺中万事非昔时，",
            "古人不在今人悲。春风不逐君王去，草色年年旧宫路。",
            "宫中歌舞已浮云，空指行人往来处。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 128. 鸡鸣曲 ----------
    {
        "id": "wang-jian-128",
        "title": "鸡鸣曲",
        "author": "王建",
        "poet_id": "wang-jian",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷46》",
        "verse": [
            "鸡初鸣，明星照东屋；鸡再鸣，红霞生海腹。",
            "百官待漏双阙前，圣人亦挂山龙服。宝钗命妇灯下起，",
            "环珮玲珑晓光里。直内初烧玉案香，司更尚滴铜壶水。",
            "金吾卫里直郎妻，到明不睡听晨鸡。天头日月相送迎，",
            "夜栖旦鸣人不迷。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 129. 送衣曲 ----------
    {
        "id": "wang-jian-129",
        "title": "送衣曲",
        "author": "王建",
        "poet_id": "wang-jian",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷47》",
        "verse": [
            "去秋送衣渡黄河，今秋送衣上陇坂。妇人不知道径处，",
            "但问新移军近远。半年著道经雨湿，开笼见风衣领急。",
            "旧来十月初点衣，与郎著向营中集。絮时厚厚绵纂纂，",
            "贵欲征人身上暖。愿身莫著裹尸归，愿妾不死长送衣。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 130. 斜路行 ----------
    {
        "id": "wang-jian-130",
        "title": "斜路行",
        "author": "王建",
        "poet_id": "wang-jian",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷48》",
        "verse": [
            "世间娶容非娶妇，中庭牡丹胜松树。九衢大道人不行，",
            "走马奔车逐斜路。斜路行熟直路荒，东西岂是横太行。",
            "南楼弹弦北户舞，行人到此多回徨。头白如丝面如茧，",
            "亦学少年行不返。纵令自解思故乡，轮折蹄穿白日晚。",
            "谁将古曲换斜音，回取行人斜路心。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 131. 织锦曲 ----------
    {
        "id": "wang-jian-131",
        "title": "织锦曲",
        "author": "王建",
        "poet_id": "wang-jian",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷49》",
        "verse": [
            "大女身为织锦户，名在县家供进簿。长头起样呈作官，",
            "闻道官家中苦难。回花侧叶与人别，唯恐秋天丝线干。",
            "红缕葳蕤紫茸软，蝶飞参差花宛转。一梭声尽重一梭，",
            "玉腕不停罗袖卷。窗中夜久睡髻偏，横钗欲堕垂著肩。",
            "合衣卧时参没后，停灯起在鸡鸣前。一匹千金亦不卖，",
            "限日未成宫里怪。锦江水涸贡转多，宫中尽著单丝罗。",
            "莫言山积无尽日，百尺高楼一曲歌。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 132. 捣衣曲（一作送衣曲） ----------
    {
        "id": "wang-jian-132",
        "title": "捣衣曲（一作送衣曲）",
        "author": "王建",
        "poet_id": "wang-jian",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷50》",
        "verse": [
            "月明中庭捣衣石，掩帷下堂来捣帛。妇姑相对神力生，",
            "双揎白腕调杵声。高楼敲玉节会成，家家不睡皆起听。",
            "秋天丁丁复冻冻，玉钗低昂衣带动。夜深月落冷如刀，",
            "湿著一双纤手痛。回编易裂看生熟，鸳鸯纹成水波曲。",
            "重烧熨斗帖两头，与郎裁作迎寒裘。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 133. 秋夜曲二首 ----------
    {
        "id": "wang-jian-133",
        "title": "秋夜曲二首",
        "author": "王建",
        "poet_id": "wang-jian",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷51》",
        "verse": [
            "天清漏长霜泊泊，兰绿收荣桂膏涸。高楼云鬟弄婵娟，",
            "古瑟暗断秋风弦。玉关遥隔万里道，金刀不剪双泪泉。",
            "香囊火死香气少，向帷合眼何时晓。城乌作营啼野月，",
            "秦州少妇生离别。",
            "秋灯向壁掩洞房，良人此夜直明光。",
            "天河悠悠漏水长，南楼北斗两相当。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 134. 题台州隐静寺 ----------
    {
        "id": "wang-jian-134",
        "title": "题台州隐静寺",
        "author": "王建",
        "poet_id": "wang-jian",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷52》",
        "verse": [
            "隐静灵仙寺天凿，杯度飞来建岩壑。五峰直上插银河，",
            "一涧当空泻寥廓。崆峒黯淡碧琉璃，白云吞吐红莲阁。",
            "不知势压天几重，钟声常闻月中落。",
            "第二百九十九卷",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 135. 送人游塞 ----------
