    # ---------- 302. 霓裳词十首 ----------
    {
        "id": "wang-jian-302",
        "title": "霓裳词十首",
        "author": "王建",
        "poet_id": "wang-jian",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷33》",
        "verse": [
            "弟子部中留一色，听风听水作霓裳。",
            "散声未足重来授，直到床前见上皇。",
            "中管五弦初半曲，遥教合上隔帘听。",
            "一声声向天头落，效得仙人夜唱经。",
            "自直梨园得出稀，更番上曲不教归。",
            "一时跪拜霓裳彻，立地阶前赐紫衣。",
            "旋翻新谱声初足，除却梨园未教人。",
            "宣与书家分手写，中官走马赐功臣。",
            "伴教霓裳有贵妃，从初直到曲成时。",
            "日长耳里闻声熟，拍数分毫错总知。",
            "弦索摐摐隔彩云，五更初发一山闻。",
            "武皇自送西王母，新换霓裳月色裙。",
            "敕赐宫人澡浴回，遥看美女院门开。",
            "一山星月霓裳动，好字先从殿里来。",
            "传呼法部按霓裳，新得承恩别作行。",
            "应是贵妃楼上看，内人舁下彩罗箱。",
            "朝元阁上山风起，夜听霓裳玉露寒。",
            "宫女月中更替立，黄金梯滑并行难。",
            "知向华清年月满，山头山底种长生。",
            "去时留下霓裳曲，总是离宫别馆声。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
