    # ---------- 381. 田侍郎归镇（一作上魏博田侍中八首） ----------
    {
        "id": "wang-jian-381",
        "title": "田侍郎归镇（一作上魏博田侍中八首）",
        "author": "王建",
        "poet_id": "wang-jian",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷112》",
        "verse": [
            "去处长将决胜筹，回回身在阵前头。",
            "贼城破后先锋入，看著红妆不敢收。",
            "熨帖朝衣抛战袍，夔龙班里侍中高。",
            "对时先奏牙间将，次第天恩与节旄。",
            "踏著家乡马脚轻，暮山秋色眼前明。",
            "老人上酒齐头拜，得侍中来尽再生。",
            "功成谁不拥藩方，富贵还须是本乡。",
            "万里双旌汾水上，玉鞭遥指白云庄。",
            "鼓吹幡旗道两边，行男走女喜骈阗。",
            "旧交省得当时别，指点如今却少年。",
            "广场破阵乐初休，彩纛高于百尺楼。",
            "老将气雄争起舞，管弦回作大缠头。",
            "笳声万里动燕山，草白天清塞马闲。",
            "触处不如别处乐，可怜秋月照江关。",
            "将士请衣忘却贫，绿窗红烛酒楼新。",
            "家家尽踏还乡曲，明月街中不绝人。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
